"""Character sums, whole families, and the quadratic twist involution.

The point count of y^2 = x^3 + A x + B over F_p equals p + 1 + S(A,B), where
S(A,B) is the quadratic character sum of the cubic.  This script verifies the
three consequences that drive the structural results:

  (1) S(A,0) = 0 for every A when p = 3 mod 4 -- the whole quartic-twist family
      y^2 = x^3 + A x is supersingular on the inert half, including the
      degenerate member A = 0;
  (2) S(0,B) = 0 for every B when p = 2 mod 3 -- the whole j = 0 family
      y^2 = x^3 + B is supersingular on its own inert half;
  (3) the twist law S(u^2 A, u^3 B) = chi(u) S(A,B), whence for a non-residue u
      the orders of a curve and its quadratic twist sum to 2p + 2; and its
      corollary that on the Gaussian split half exactly one of the two
      quartic-twist orbits has order divisible by 8.
"""

from __future__ import annotations


def primes_up_to(n: int) -> list[int]:
    s = bytearray([1]) * (n + 1)
    s[0:2] = b"\x00\x00"
    for i in range(2, int(n**0.5) + 1):
        if s[i]:
            s[i * i :: i] = bytearray(len(s[i * i :: i]))
    return [i for i in range(n + 1) if s[i]]


def legendre(a: int, p: int) -> int:
    a %= p
    return 0 if a == 0 else (1 if pow(a, (p - 1) // 2, p) == 1 else -1)


def char_sum(A: int, B: int, p: int) -> int:
    """S(A,B) = sum over x of chi(x^3 + A x + B)."""
    return sum(legendre((x * x % p * x + A * x + B) % p, p) for x in range(p))


def curve_card(A: int, B: int, p: int) -> int:
    return p + 1 + char_sum(A, B, p)


def non_residue(p: int) -> int:
    return next(u for u in range(2, p) if legendre(u, p) == -1)


def main(limit: int = 200) -> None:
    print("(1) Quartic family y² = x³ + A x on the Gaussian inert half p = 3 mod 4")
    tested = 0
    for p in primes_up_to(limit):
        if p % 4 != 3:
            continue
        for A in range(p):
            assert char_sum(A, 0, p) == 0, (p, A)
            assert curve_card(A, 0, p) == p + 1
            tested += 1
    print(f"    S(A,0) = 0 for all {tested} pairs (A, p) tested — "
          "every member has exactly p+1 points.\n")

    print("(2) j = 0 family y² = x³ + B on the Eisenstein inert half p = 2 mod 3")
    tested = 0
    for p in primes_up_to(limit):
        if p <= 3 or p % 3 != 2:
            continue
        for B in range(p):
            assert char_sum(0, B, p) == 0, (p, B)
            tested += 1
    print(f"    S(0,B) = 0 for all {tested} pairs (B, p) tested.\n")

    print("(3) The quadratic twist law  #E + #E^u = 2p + 2")
    print(f"    {'p':>5} {'u':>3} {'#E':>6} {'#E^u':>6} {'sum':>6} {'2p+2':>6}"
          f" {'mod 8':>10}")
    for p in [p for p in primes_up_to(120) if p > 3]:
        u = non_residue(p)
        n1 = curve_card(1, 0, p)
        n2 = curve_card(u * u % p, 0, p)
        assert n1 + n2 == 2 * p + 2
        # twist law at the level of character sums
        assert char_sum(u * u % p, 0, p) == legendre(u, p) * char_sum(1, 0, p)
        tag = ""
        if p % 4 == 1:
            assert n1 % 4 == 0 and n2 % 4 == 0
            assert (n1 % 8 == 0) != (n2 % 8 == 0)
            tag = f"{n1 % 8}, {n2 % 8}"
        print(f"    {p:>5} {u:>3} {n1:>6} {n2:>6} {n1+n2:>6} {2*p+2:>6} {tag:>10}")
    print("\n    On the split half both orders are divisible by 4 and their sum is")
    print("    4 mod 8, so exactly one of the two twists has order divisible by 8.")

    print("\n(4) The Gauss parameter is odd: a_p = 2 mod 4 on the split half")
    for p in [p for p in primes_up_to(160) if p % 4 == 1]:
        a_p = p + 1 - curve_card(1, 0, p)
        assert a_p % 4 == 2 % 4 or (-a_p) % 4 == 2
        print(f"    p = {p:>3}:  a_p = {a_p:>4},  a_p mod 4 = {a_p % 4},  "
              f"Gauss parameter a = {abs(a_p)//2} (odd: {abs(a_p)//2 % 2 == 1})")


if __name__ == "__main__":
    main()
